CREATE TABLE costs (cost_month VARCHAR2(400), region_id NUMBER, product_id NUMBER, unit_cogs NUMBER, freight_per_unit NUMBER, carrier VARCHAR2(400));
CREATE TABLE customers (customer_id NUMBER, customer_name VARCHAR2(400), region_id NUMBER, segment VARCHAR2(400), contact_email VARCHAR2(400), credit_limit NUMBER);
CREATE TABLE discounts (discount_id NUMBER, region_id NUMBER, program_name VARCHAR2(400), start_date VARCHAR2(400), end_date VARCHAR2(400), max_discount_pct NUMBER, approved_by VARCHAR2(400), approver_level VARCHAR2(400));
CREATE TABLE products (product_id NUMBER, product_name VARCHAR2(400), category VARCHAR2(400), list_price NUMBER);
CREATE TABLE regions (region_id NUMBER, region_name VARCHAR2(400), manager VARCHAR2(400));
CREATE TABLE sales (sale_id NUMBER, sale_date VARCHAR2(400), sale_month VARCHAR2(400), sale_quarter VARCHAR2(400), customer_id NUMBER, product_id NUMBER, region_id NUMBER, quantity NUMBER, unit_price NUMBER, discount_pct NUMBER, net_revenue NUMBER);
